JOIN brands b ON b.name = v.brand
ON CONFLICT (brand_id) DO UPDATE SET
    score = EXCLUDED.score, studies = EXCLUDED.studies, sources = EXCLUDED.sources,
    method = EXCLUDED.method, as_of = EXCLUDED.as_of;

-- Brands no study covers: their engines' average as it was.
INSERT INTO brand_reliability (brand_id, score, studies, sources, method, as_of)
SELECT b.id, ROUND(AVG(e.reliability_score), 1), 0, '[]'::jsonb, 'Sem estudos publicados para a marca: mantém-se a estimativa anterior.', DATE '2026-11-14'
FROM brands b JOIN vehicle_models vm ON vm.brand_id = b.id JOIN engines e ON e.model_id = vm.id
WHERE NOT EXISTS (SELECT 1 FROM brand_reliability r WHERE r.brand_id = b.id)
GROUP BY b.id
ON CONFLICT (brand_id) DO NOTHING;

WITH before AS (
    SELECT vm.brand_id, AVG(e.reliability_score) AS mean
    FROM engines e JOIN vehicle_models vm ON vm.id = e.model_id
    WHERE e.reliability_basis IS NULL
    GROUP BY vm.brand_id
)
UPDATE engines e
SET reliability_score = ROUND(LEAST(10, GREATEST(1,
        r.score + LEAST(0.6, GREATEST(-1.0, e.reliability_score - before.mean))))::numeric, 1),
    reliability_basis = CASE WHEN r.studies > 0
                             THEN 'marca: ' || r.studies || ' estudos publicados; desvio do motor: editorial'
                             ELSE 'estimativa editorial (marca sem estudos publicados)' END
FROM vehicle_models vm
JOIN brand_reliability r ON r.brand_id = vm.brand_id
JOIN before ON before.brand_id = vm.brand_id
WHERE vm.id = e.model_id AND e.reliability_basis IS NULL;

COMMIT;

-- Verify: brand anchors next to the average of their engines.
SELECT b.name, r.score AS anchor, r.studies,
       ROUND(AVG(e.reliability_score), 1) AS engines_avg, COUNT(e.id) AS engines
FROM brand_reliability r JOIN brands b ON b.id = r.brand_id
LEFT JOIN vehicle_models vm ON vm.brand_id = b.id LEFT JOIN engines e ON e.model_id = vm.id
GROUP BY b.name, r.score, r.studies ORDER BY r.score DESC;
